#!/bin/sh
# Railway wrapper for the Homelable backend.
# - Refuses to start without SECRET_KEY and an admin password (no admin/admin default).
# - Turns ADMIN_PASSWORD into the bcrypt AUTH_PASSWORD_HASH Homelable expects,
#   so the password can be generated by Railway and rotated by editing one variable.
set -eu

if [ -z "${SECRET_KEY:-}" ]; then
  echo "homelable: SECRET_KEY is not set; refusing to start." >&2
  exit 1
fi

if [ -n "${ADMIN_PASSWORD:-}" ]; then
  AUTH_PASSWORD_HASH="$(python -c 'import os, bcrypt; print(bcrypt.hashpw(os.environ["ADMIN_PASSWORD"].encode(), bcrypt.gensalt()).decode())')"
  export AUTH_PASSWORD_HASH
elif [ -z "${AUTH_PASSWORD_HASH:-}" ] && [ "${AUTH_MODE:-local}" = "local" ]; then
  echo "homelable: set ADMIN_PASSWORD (or AUTH_PASSWORD_HASH); refusing to start with no admin password." >&2
  exit 1
fi
unset ADMIN_PASSWORD

export AUTH_USERNAME="${AUTH_USERNAME:-admin}"
export SQLITE_PATH="${SQLITE_PATH:-/app/data/homelab.db}"
mkdir -p "$(dirname "$SQLITE_PATH")"

exec uvicorn app.main:app --host 0.0.0.0 --port "${PORT:-8000}" \
  --proxy-headers --forwarded-allow-ips='*'
